def load() -> pd.DataFrame:
    import csv
    rows = []
    with open('data/environment/input/pleasure_bay_and_castle_island_beach_datasheet.csv', encoding='latin-1') as f:
        reader = csv.reader(f)
        for i, row in enumerate(reader):
            rows.append({'row_num': i, 'content': str(row)})
            if i >= 20:
                break
    return pd.DataFrame(rows)
